head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onbeforesort]<br/>sortable=true 인 Header Column 을 클릭 또는 더블 클릭하여 데이터가 정렬되기 전에 발생합니다.",
    "validation" : [
        "sortEvent 속성이 'onclick' 이면 Header Cell 클릭 시, 'ondblclick' 이면 더블 클릭 시 이벤트가 발생합니다.",
        "true 를 반환하면 정렬을 실행하고 onsort 이벤트를 발생시킵니다.",
        "false 를 반환하면 정렬을 취소하고 onsort 이벤트를 발생시키지 않습니다.",
        "sortInfo.sortOrder 파라미터값이 0 일 경우 반환값이 무시되고 true 로 동작합니다.",
        "반환값을 생략할 경우 true 로 적용됩니다.",
        "onbeforesort 이벤트에서 false 를 반환하는 경우 실제 정렬만 수행하지 않을뿐 해당 Header Column 의 정렬 상태는 변경됩니다.",
        "Header Column 클릭 시 [onheaderclick/onheaderdblclick] > onbeforesort > onsort 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 이벤트 순서 누적 로그 초기화
    scwin.gVar = { "eventLog": [] };

    // 조건 값 읽기
    //  - con_returnValue : 핸들러 반환값 제어 (true / false / 미설정=생략)
    //  - con_sortEvent   : 정렬 트리거 방식 (onclick / ondblclick)
    let returnValueVal = con_returnValue.getValue();
    let sortEventVal = con_sortEvent.getValue();

    // 현재 설정/검증 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="sortable=true 헤더(name)를 정렬하면 [onheaderclick/onheaderdblclick] > onbeforesort > onsort 순서로 로그가 출력됩니다. / 초기 표시순서: Cherry, Apple, Date, Banana / 정렬은 클릭마다 오름(1)->내림(-1)->해제(0) 순환"', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: 핸들러 반환값=' + (returnValueVal === '' ? '생략(undefined->true)' : returnValueVal) + ' / sortEvent=' + sortEventVal + ' / false 반환 시 정렬은 취소되나 정렬상태(getSortableStatus)는 변경됨(@spec) / sortOrder=0(해제)이면 반환값 무시되고 항상 실행"', '', 'label2');

    // dataList 직접 생성 (4행, 정렬 시 순서가 눈에 띄게 바뀌도록 col1 값 구성)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    let nameArr = ['Cherry', 'Apple', 'Date', 'Banana'];
    let descArr = ['체리', '사과', '대추', '바나나'];
    for (let r = 0; r < 4; r++) {
        strDl += '<w2:row>';
        strDl += '<col1>' + nameArr[r] + '</col1>';
        strDl += '<col2>' + descArr[r] + '</col2>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // target 생성 : sortable=true / showSortableImage=true 고정, sortEvent 조건 적용
    //  - 단일 Row 헤더(병합 금지) : 병합헤더는 정렬 인덱스 어긋남
    //  - onheaderclick / onheaderdblclick / onbeforesort / onsort 모두 바인딩 (이벤트 순서 검증)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' sortEvent="' + sortEventVal + '" sortable="true" showSortableImage="true" dataList="data:dlt_bind" checkAllType="false" id="" ev:onheaderclick="scwin.target1_onheaderclick" ev:onheaderdblclick="scwin.target1_onheaderdblclick" ev:onbeforesort="scwin.target1_onbeforesort" ev:onsort="scwin.target1_onsort" style="width:420px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="column2" value="desc"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 현재 화면 표시순서(col1=name) 수집 (정렬 실행/취소 여부 확인용)
scwin.getDisplayOrder = function () {
    let order = [];
    let rowCnt = target1.getRowCount();
    for (let i = 0; i < rowCnt; i++) {
        let v = target1.getCellDisplayData(i, "col1");
        v = (v == null ? "" : ("" + v)).trim();
        if (v !== "") {
            order.push(v);
        }
    }
    return order.join(", ");
};



// onheaderclick : sortEvent="onclick" 환경에서 정렬 트리거 시 가장 먼저 발생 (@spec2)
scwin.target1_onheaderclick = function (headerId) {
    scwin.gVar.eventLog.push("onheaderclick");
};



// onheaderdblclick : sortEvent="ondblclick" 환경에서 정렬 트리거 시 가장 먼저 발생 (@spec2)
scwin.target1_onheaderdblclick = function (headerId) {
    scwin.gVar.eventLog.push("onheaderdblclick");
};



// onbeforesort : 정렬 직전 발생, 핸들러 반환값으로 정렬 실행 여부 제어 (이벤트 핵심)
//  - con_returnValue : true -> return true / false -> return false / 미설정 -> return 문 없음(undefined->true)
//  - sortInfo 개별 속성(headerId / bodyColId / sortOrder) 출력
//  - sortOrder===0(해제) 이면 반환값 무시되고 true 동작 (@return)
scwin.target1_onbeforesort = function (sortInfo) {
    scwin.gVar.eventLog.push("onbeforesort");

    let returnValueVal = con_returnValue.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforesort=====");
    wf_body_bottom.getObj("scwin").setReturnValue("sortInfo.headerId : " + sortInfo.headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("sortInfo.bodyColId : " + sortInfo.bodyColId);
    wf_body_bottom.getObj("scwin").setReturnValue("sortInfo.sortOrder : " + sortInfo.sortOrder + " (1:오름차순 / -1:내림차순 / 0:정렬해제)");
    wf_body_bottom.getObj("scwin").setReturnValue("적용 반환값 : " + (returnValueVal === '' ? '생략(undefined->true)' : returnValueVal));

    // sortOrder===0(해제) 안내 : 반환값 무시되고 true 동작
    if (sortInfo.sortOrder === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("sortOrder=0(해제) : 반환값 무시되고 true 로 동작 -> 정렬해제 실행 + onsort 발생");
    }

    // 반환값 제어
    if (returnValueVal === 'true') {
        return true;
    } else if (returnValueVal === 'false') {
        return false;
    }
    // 미설정 : return 문 없음 -> undefined -> true 적용
};



// onsort : onbeforesort 가 true(또는 해제) 일 때만 발생 (false 반환 시 미발생)
//  - 발생 자체가 '정렬 실행됨'의 신호
//  - 정렬 후 표시순서 + 이벤트 발생 순서(@spec2) 출력
scwin.target1_onsort = function (sortInfo) {
    scwin.gVar.eventLog.push("onsort");
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onsort===== (정렬 실행됨)");
    wf_body_bottom.getObj("scwin").setReturnValue("정렬 후 표시순서(name) : " + scwin.getDisplayOrder());
    wf_body_bottom.getObj("scwin").setReturnValue("이벤트 발생 순서 : " + scwin.gVar.eventLog.join(" > "));
    scwin.gVar.eventLog = [];
};



// 정렬 결과 확인 : 표시순서(실제 정렬 결과) vs getSortableStatus(정렬 상태) 대비 (@spec)
//  - false 반환 시 : 표시순서는 미변경(정렬 취소) 이나 getSortableStatus 는 변경됨 -> 불일치 확인
scwin.btn_checkSortStatus_onclick = function () {
    let status = target1.getSortableStatus();
    wf_body_bottom.getObj("scwin").setReturnValue("=====정렬 상태 확인=====");
    wf_body_bottom.getObj("scwin").setReturnValue("현재 표시순서(name) : " + scwin.getDisplayOrder());
    wf_body_bottom.getObj("scwin").setReturnValue("getSortableStatus() : " + JSON.stringify(status));
    // 이벤트 순서 누적 로그가 남아있으면(onsort 미발생=false 반환) 함께 출력
    if (scwin.gVar.eventLog.length > 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("직전 이벤트 순서(onsort 미발생) : " + scwin.gVar.eventLog.join(" > "));
        scwin.gVar.eventLog = [];
    }
};
